import java.util.Arrays;

public class ScoreBumperTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        int[] scores = {1, 2, 3};
        ScoreBumper.bumpInPlace(scores, 10);
        check("bumpInPlace changes the caller's array",
                "[11, 12, 13]", Arrays.toString(scores));

        int[] copy = ScoreBumper.bumpedCopy(scores, 1);
        check("bumpedCopy returns the bumped values", "[12, 13, 14]", Arrays.toString(copy));
        check("bumpedCopy leaves the original alone", "[11, 12, 13]", Arrays.toString(scores));
        check("the copy is a different object", false, ScoreBumper.sameArray(scores, copy));
        check("a reference compared with itself", true, ScoreBumper.sameArray(scores, scores));

        int[] twin = {11, 12, 13};
        check("equal contents are still two objects", false, ScoreBumper.sameArray(scores, twin));
        check("two nulls are the same reference", true, ScoreBumper.sameArray(null, null));

        ScoreBumper.bumpInPlace(null, 5);
        check("a null array is bumped harmlessly", "[]", Arrays.toString(ScoreBumper.bumpedCopy(null, 5)));

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

