import java.util.Arrays;

/**
 * TASK: Complete ScoreBumper and show the difference between changing the
 * array a reference points AT and handing back a brand new array.
 *
 * Rules:
 *   - bumpInPlace(scores, amount) adds amount to every element of the SAME
 *     array the caller passed in; a null array is simply ignored
 *   - bumpedCopy(scores, amount) leaves the caller's array untouched and
 *     returns a NEW array holding the bumped values; a null array gives back
 *     an empty array
 *   - sameArray(a, b) reports whether the two references point at the exact
 *     same array object -- use ==, never Arrays.equals; two nulls count as
 *     the same
 *
 * Example: int[] s = {1, 2}; bumpInPlace(s, 10) makes s {11, 12},
 *   while bumpedCopy(s, 1) returns {12, 13} and leaves s as {11, 12}.
 */
public class ScoreBumper {

    public static void bumpInPlace(int[] scores, int amount) {
        if (scores == null) {
            return;
        }
        for (int i = 0; i < scores.length; i++) {
            scores[i] = scores[i] + amount;
        }
    }

    public static int[] bumpedCopy(int[] scores, int amount) {
        if (scores == null) {
            return new int[0];
        }
        int[] copy = Arrays.copyOf(scores, scores.length);
        for (int i = 0; i < copy.length; i++) {
            copy[i] = copy[i] + amount;
        }
        return copy;
    }

    public static boolean sameArray(int[] a, int[] b) {
        return a == b;
    }
}
